// Turns each row of the competitor list into a price check.
// A row can have a product (ASIN, Amazon URL, or product name), a competitor name, or both.
// A row with only a competitor name searches Amazon for that competitor's products.
const settings = $('Settings').first().json;
const rows = $('Get Competitor List').all().map((i) => i.json);

const toInt = (value, fallback) => {
  const n = parseInt(String(value ?? '').trim(), 10);
  return Number.isFinite(n) ? n : fallback;
};
const clamp = (n, min, max) => Math.min(Math.max(n, min), max);
const defaultMax = clamp(toInt(settings.default_max_products, 5), 1, 20);

const cleanMarketplace = (value) => String(value ?? '').trim().toLowerCase()
  .replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');

const ASIN_IN_URL = /\/(?:dp|gp\/product|gp\/aw\/d|product)\/([A-Z0-9]{10})(?=[/?#]|$)/i;
const out = [];
const competitorSearches = new Map();

for (const row of rows) {
  const competitor = String(row.competitor ?? '').trim();
  const product = String(row.product ?? '').trim();
  if (!competitor && !product) continue;

  let marketplace = cleanMarketplace(row.marketplace) || 'amazon.com';
  const base = { list_row: row.row_number, competitor, input: product || competitor, marketplace };
  const add = (json) => out.push({ json: { ...base, ...json }, pairedItem: { item: 0 } });
  const fail = (code, error) => add({ lookup: 'error', ok: false, code, error });

  if (!/^amazon\.[a-z.]+$/.test(marketplace)) {
    fail('invalid_request', `"${row.marketplace}" isn't an Amazon site. Use a domain such as amazon.com or amazon.co.uk.`);
    continue;
  }

  // Only a competitor name: search Amazon for their products
  if (!product) {
    const key = `${competitor.toLowerCase()}|${marketplace}`;
    if (competitorSearches.has(key)) {
      fail('duplicate', `This competitor is already searched in row ${competitorSearches.get(key)}.`);
      continue;
    }
    competitorSearches.set(key, row.row_number);
    const maxProducts = clamp(toInt(row.max_products, defaultMax), 1, 20);
    add({
      lookup: 'competitor',
      found_by: 'competitor search',
      max_products: maxProducts,
      searchUrl: `https://www.${marketplace}/s?k=${encodeURIComponent(competitor)}`,
      searchPrompt:
        `This is an Amazon search results page for "${competitor}". Find the products on this page that are made ` +
        `or sold by "${competitor}" (check the brand and the product title). Skip products from other brands, ` +
        `including sponsored products. Return up to ${maxProducts} products in the order they appear, as a JSON ` +
        `object with a "products" array. For each product give: asin (the 10-character ASIN), title, and url ` +
        `(the product page link).`,
    });
    continue;
  }

  // A product link
  const link = product.match(/https?:\/\/\S+/i)?.[0].replace(/[).,!?]+$/, '');
  if (link) {
    // (URL() isn't available in n8n's Code node, so read the host with a pattern)
    const host = (link.match(/^https?:\/\/([^/?#:\s]+)/i)?.[1] ?? '').toLowerCase().replace(/^www\./, '');
    const isAmazon = /^(smile\.)?amazon\.[a-z.]+$/.test(host);
    const isShortLink = /^(amzn\.(to|eu|asia)|a\.co)$/.test(host);
    if (!isAmazon && !isShortLink) {
      fail('invalid_request', `Only Amazon links are supported, but this link is on ${host || 'an unknown site'}.`);
      continue;
    }
    if (isAmazon) marketplace = host.replace(/^smile\./, '');
    const asin = link.match(ASIN_IN_URL)?.[1]?.toUpperCase() ?? '';
    add({
      marketplace,
      lookup: 'url',
      found_by: 'list',
      asin,
      // A clean /dp/ URL avoids tracking parameters; short links are passed on for Pumice to follow
      amazonUrl: asin ? `https://www.${marketplace}/dp/${asin}` : link,
    });
    continue;
  }

  // An ASIN: 10 letters and digits with at least one digit
  if (/^(?=.*\d)[A-Z0-9]{10}$/i.test(product)) {
    const asin = product.toUpperCase();
    add({ lookup: 'url', found_by: 'list', asin, amazonUrl: `https://www.${marketplace}/dp/${asin}` });
    continue;
  }

  // A product name that was already matched on an earlier run: price the saved ASIN
  const savedAsin = String(row.matched_asin ?? '').trim().toUpperCase();
  if (/^(?=.*\d)[A-Z0-9]{10}$/.test(savedAsin)) {
    add({ lookup: 'url', found_by: 'product search', asin: savedAsin, amazonUrl: `https://www.${marketplace}/dp/${savedAsin}` });
    continue;
  }

  // A product name: search for it, adding the competitor name if the product name doesn't include it
  const searchQuery = competitor && !product.toLowerCase().includes(competitor.toLowerCase())
    ? `${competitor} ${product}`
    : product;
  add({ lookup: 'search', found_by: 'product search', asin: '', amazonUrl: '', searchQuery });
}

return out;

// Takes the top Amazon product pages from Pumice Universal Search for each product name row.
// Each one is scraped and checked with Pumice product matching before it is used.
const MAX_CANDIDATES = 3;
const ASIN_IN_URL = /\/(?:dp|gp\/product|gp\/aw\/d)\/([A-Z0-9]{10})(?=[/?#]|$)/i;
const out = [];

$input.all().forEach((item, i) => {
  let request;
  try {
    request = $('How to Find the Product?').itemMatching(i).json;
  } catch (e) {
    request = $('How to Find the Product?').all(0)[i].json;
  }
  const res = item.json;

  // The response shape can vary, so check the common containers
  let list = res.results ?? res.data ?? res.items ?? res.pages ?? res.urls ?? res.organic ?? [];
  if (list && !Array.isArray(list) && Array.isArray(list.results)) list = list.results;
  if (!Array.isArray(list)) list = [];

  const seen = new Set();
  const pages = [];
  for (const r of list) {
    const url = typeof r === 'string' ? r : (r?.url || r?.link || r?.source_url || r?.page_url || '');
    // (URL() isn't available in n8n's Code node, so read the host with a pattern)
    const host = (String(url).match(/^https?:\/\/([^/?#:\s]+)/i)?.[1] ?? '').toLowerCase().replace(/^www\./, '');
    const asin = String(url).match(ASIN_IN_URL)?.[1]?.toUpperCase();
    // Only product pages on the row's marketplace
    if (host !== request.marketplace || !asin || seen.has(asin)) continue;
    seen.add(asin);
    pages.push(asin);
    if (pages.length >= MAX_CANDIDATES) break;
  }

  if (!pages.length) {
    const reason = typeof res.error === 'string' ? res.error : res.error?.message;
    out.push({
      json: {
        ...request,
        lookup: 'error',
        ok: false,
        code: reason ? 'scrape_failed' : 'not_found',
        error: reason
          ? `Pumice Universal Search failed (${reason}). It will be tried again on the next run.`
          : `No ${request.marketplace} product page was found for "${request.searchQuery}". Use the ASIN or the Amazon product URL instead.`,
      },
      pairedItem: { item: i },
    });
    return;
  }

  pages.forEach((asin, rank) => {
    out.push({
      json: {
        ...request,
        asin,
        amazonUrl: `https://www.${request.marketplace}/dp/${asin}`,
        candidate_rank: rank + 1,
        candidate_count: pages.length,
      },
      pairedItem: { item: i },
    });
  });
});

return out;

