// Builds the two product records for Pumice product matching:
// product_1 is the row you entered, product_2 is the Amazon page Smart Scrape just read.
const candidate = $('Pick Amazon Candidates').item.json;
const res = $input.item.json;

let d = res.data ?? res.result ?? res.output ?? res.extracted ?? res;
if (typeof d === 'string') {
  try { d = JSON.parse(d); } catch (e) { d = {}; }
}
if (Array.isArray(d)) d = d[0] ?? {};
d = d && typeof d === 'object' ? d : {};
const text = (v) => (Array.isArray(v) ? v.join(' ') : String(v ?? '')).trim();

const scraped = {
  title: text(d.title ?? d.product_title),
  brand: text(d.brand),
  mpn: text(d.model_number ?? d.mpn ?? d.model),
  description: text(d.description ?? d.features).slice(0, 1500),
};

return {
  json: {
    ...candidate,
    scraped_title: scraped.title,
    // The product matching endpoint expects each product as a JSON string
    product_1: JSON.stringify({ title: candidate.input, brand: candidate.competitor }),
    product_2: JSON.stringify(scraped),
  },
};

// Reads Pumice product matching's answer for one candidate: yes, no, or error.
const candidate = $('Prepare Match').item.json;
const res = $input.item.json;
const answer = String(res.answer ?? res.data?.answer ?? res.result?.answer ?? '').trim().toLowerCase();
const reason = typeof res.error === 'string' ? res.error : res.error?.message;

const { product_1, product_2, ...rest } = candidate;
return {
  json: {
    ...rest,
    match: answer === 'yes' ? 'yes' : answer === 'no' ? 'no' : 'error',
    match_error: answer === 'yes' || answer === 'no' ? '' : (reason || 'No answer from product matching'),
  },
};

// Picks, for each product name row, the highest-ranked search result that product matching
// confirmed is the same product. Rows where no result matched get an error instead.
const rows = new Map();
const out = [];

$input.all().forEach((item, i) => {
  const r = item.json;
  if (r.ok === false) {
    out.push({ json: r, pairedItem: { item: i } });
    return;
  }
  if (!rows.has(r.list_row)) rows.set(r.list_row, []);
  rows.get(r.list_row).push({ r, i });
});

for (const list of rows.values()) {
  list.sort((a, b) => a.r.candidate_rank - b.r.candidate_rank);
  const hit = list.find(({ r }) => r.match === 'yes');
  const { r: first, i } = hit ?? list[0];
  const { candidate_rank, candidate_count, match, match_error, scraped_title, ...base } = first;

  if (hit) {
    out.push({ json: { ...base, lookup: 'url' }, pairedItem: { item: i } });
    continue;
  }

  const allFailed = list.every(({ r }) => r.match === 'error');
  const checked = list
    .map(({ r }) => `${r.asin}${r.scraped_title ? ` (${r.scraped_title.slice(0, 60)})` : ''}`)
    .join(', ');
  out.push({
    json: {
      ...base,
      asin: '',
      amazonUrl: '',
      lookup: 'error',
      ok: false,
      code: allFailed ? 'match_failed' : 'no_match',
      error: allFailed
        ? `Pumice product matching failed (${first.match_error}). It will be tried again on the next run.`
        : `None of the top ${list.length} Amazon results matched "${base.input}". Checked: ${checked}. Add the ASIN or product URL to the row instead.`,
    },
    pairedItem: { item: i },
  });
}

return out;

// Reads the competitor's products from Pumice Smart Scrape's reading of the Amazon search page,
// and outputs one item per product so each one can be priced.
const ASIN_RE = /^(?=.*\d)[A-Z0-9]{10}$/;
const ASIN_IN_URL = /\/(?:dp|gp\/product|gp\/aw\/d)\/([A-Z0-9]{10})(?=[/?#]|$)/i;
const out = [];

const parse = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (e) { return null; }
};

$input.all().forEach((item, i) => {
  let request;
  try {
    request = $('How to Find the Product?').itemMatching(i).json;
  } catch (e) {
    request = $('How to Find the Product?').all(1)[i].json;
  }
  const res = item.json;
  const fail = (code, error) =>
    out.push({ json: { ...request, lookup: 'error', ok: false, code, error }, pairedItem: { item: i } });

  if (res.error && res.data === undefined && res.result === undefined) {
    const reason = typeof res.error === 'string' ? res.error : res.error?.message;
    fail('scrape_failed', `Pumice couldn't read the Amazon search page${reason ? ` (${reason})` : ''}. It will be tried again on the next run.`);
    return;
  }

  // The products can arrive as an array, or under products/items/results, as objects or a JSON string
  let d = parse(res.data ?? res.result ?? res.output ?? res.extracted ?? res);
  let list = Array.isArray(d) ? d : parse(d?.products ?? d?.items ?? d?.results ?? []);
  if (!Array.isArray(list)) list = [];

  const seen = new Set();
  const found = [];
  for (const p of list) {
    if (!p) continue;
    const obj = typeof p === 'string' ? { url: p } : p;
    let asin = String(obj.asin ?? '').trim().toUpperCase();
    if (!ASIN_RE.test(asin)) {
      asin = String(obj.url ?? obj.link ?? obj.product_url ?? '').match(ASIN_IN_URL)?.[1]?.toUpperCase() ?? '';
    }
    if (!asin || seen.has(asin)) continue;
    seen.add(asin);
    found.push(asin);
    if (found.length >= request.max_products) break;
  }

  if (!found.length) {
    fail('not_found', `No products from "${request.competitor}" were found on ${request.marketplace}. Check the spelling, or add the competitor's ASINs as their own rows.`);
    return;
  }

  for (const asin of found) {
    out.push({
      json: { ...request, lookup: 'url', asin, amazonUrl: `https://www.${request.marketplace}/dp/${asin}` },
      pairedItem: { item: i },
    });
  }
});

return out;

// Keeps one price check per product and marketplace. Products listed by ASIN or URL come first,
// then product name searches, then competitor searches, so the first one wins.
const firstRow = new Map();

return $input.all().map((item, i) => {
  const j = item.json;
  if (j.ok === false || !j.asin) return { json: j, pairedItem: { item: i } };

  const key = `${j.marketplace}:${j.asin}`;
  if (firstRow.has(key)) {
    return {
      json: { ...j, ok: false, code: 'duplicate', error: `${j.asin} is already tracked from row ${firstRow.get(key)}.` },
      pairedItem: { item: i },
    };
  }
  firstRow.set(key, j.list_row);
  return { json: j, pairedItem: { item: i } };
});

